#include <set>
#include <iostream>

int main() {
    std::set<int> data = {10, 20, 30, 40, 50};
    int target = 25;

    // O(log N) lookup using the container member function
    auto it = data.lower_bound(target);

    if (it != data.end()) {
        // Finds the first element >= 25, which is 30
        std::cout << "First element >= " << target << ": " << *it << "\n";
    } else {
        std::cout << "Target is too large.\n";
    }

    // Check if 40 exists (using lower_bound)
    target = 40;
    it = data.lower_bound(target);
    if (it != data.end() && *it == target) {
        std::cout << target << " found.\n";
    }
}
